/* ===== Numeria Quest — Senjata hero mengikuti equipment =====
   Dimuat SEBELUM hero_pixel.js. Gambar hero di hero_pixel.js sekarang TANPA senjata; modul ini menggambar senjata
   dari equipment yang dipakai (Pl.eq.w, katalog di equip_katalog.js) di tangan hero, di semua pose:
   battle (diam / serang), dunia, dan pratinjau pilih job.
   - Pedang -> Pendekar Pedang, Busur -> Pemanah, Tongkat Sihir -> Penyihir (hanya yang cocok dengan job).
   - Tanpa senjata cocok yang terpasang, hero memegang senjata dasar (Pedang Besi / Busur Kayu / Tongkat Kayu).
   - Senjata Rare ke atas diberi cahaya tipis sesuai warna tingkatnya.
   Posisi tangan, sudut, dan panjang per pose ada di tabel PLACE (koordinat kanvas hero 163x128). */
const HEROWPN = (() => {
  const CW = 80,
    CH = 112,
    COLS = 15,
    PLACE = {
      sword_front: { g: [51, 80], th: -141.3, L: 70, a: [40, 98] },
      sword_act: { g: [100, 76], th: 119.5, L: 76, a: [40, 98] },
      archer_front: { g: [94, 74], th: 39.6, L: 70, a: [40, 56] },
      archer_act: { g: [106, 68], th: -7.7, L: 84, a: [40, 56] },
      mage_front: { g: [47, 62], th: -14, L: 74, a: [40, 78] },
      mage_act: { g: [92, 50], th: 33, L: 64, a: [40, 78] },
    },
    RK = ["pd", "bs", "tk"],
    JB = ["sword", "archer", "mage"],
    GLOW = [null, null, "#4db8ff", "#b070ff", "#ffc233"],
    DEF = { sword: "pd0_0", archer: "bs0_0", mage: "tk0_0" };
  const img = new Image(),
    api = { ready: false };
  let white = null;
  img.onload = () => (api.ready = true);
  img.src =
    "data:image/png;base64,";
  const whiteAtlas = () => {
    if (white) return white;
    const c = document.createElement("canvas");
    c.width = img.width;
    c.height = img.height;
    const x = c.getContext("2d");
    x.drawImage(img, 0, 0);
    x.globalCompositeOperation = "source-in";
    x.fillStyle = "#fff";
    x.fillRect(0, 0, c.width, c.height);
    return (white = c);
  };
  /* kunci senjata yang dipakai untuk job ini */
  const keyFor = (jb) => {
    const k = typeof Pl !== "undefined" && Pl && Pl.eq && Pl.eq.w,
      m = k && /^(pd|bs|tk)(\d)_(\d)$/.exec(k);
    return m && JB[RK.indexOf(m[1])] === jb ? k : DEF[jb];
  };
  api.indexOf = (k) => {
    const m = /^(pd|bs|tk)(\d)_(\d)$/.exec(k);
    return m ? RK.indexOf(m[1]) * 25 + +m[2] * 5 + +m[3] : 0;
  };
  /* c = konteks, jb = job, pose = "idle"|"act", (ox,oy) = pojok kiri-atas gambar hero, s = skala, flash = siluet putih, smooth = haluskan */
  api.draw = (c, jb, pose, ox, oy, s, flash, smooth) => {
    const p = PLACE[jb + "_" + (pose === "act" ? "act" : "front")];
    if (!api.ready || !p) return;
    const k = keyFor(jb),
      i = api.indexOf(k),
      t = +k[2],
      kk = (p.L / 108) * s;
    c.save();
    c.imageSmoothingEnabled = !!smooth;
    c.imageSmoothingQuality = "high";
    if (!flash && GLOW[t]) {
      c.shadowColor = GLOW[t];
      c.shadowBlur = 3 + (t - 2) * 3;
    }
    c.translate(ox + p.g[0] * s, oy + p.g[1] * s);
    c.rotate((p.th * Math.PI) / 180);
    c.scale(kk, kk);
    c.drawImage(
      flash ? whiteAtlas() : img,
      (i % COLS) * CW,
      ((i / COLS) | 0) * CH,
      CW,
      CH,
      -p.a[0],
      -p.a[1],
      CW,
      CH,
    );
    c.restore();
  };
  return api;
})();
